<section class="page-heading compact-heading"><div><p class="eyebrow">SUBJECT DETAILS</p><h1><?= e($subject['name']) ?>.</h1><p class="heading-copy"><?= e($subject['description'] ?: 'A place for related study tasks.') ?></p></div><div class="heading-actions"><a class="secondary-button" href="<?= e(url('/subjects/' . $subject['id'] . '/edit')) ?>">Edit subject</a><a class="back-button" href="<?= e(url('/subjects')) ?>">All subjects</a></div></section>
<section class="content-section">
    <div class="section-heading"><div><p class="eyebrow">SUBJECT WORKLOAD</p><h2><?= (int) $subject['task_count'] ?> tasks <span class="dot-separator">·</span> <?= (int) $subject['completed_count'] ?> completed</h2></div><a class="primary-button" href="<?= e(url('/tasks/create')) ?>">+ Add task</a></div>
    <?php if ($tasks === []): ?><div class="empty-state compact-empty"><h3>No tasks for this subject yet</h3><p>Add the first task to start tracking your work here.</p></div><?php else: ?>
        <ul class="task-list"><?php foreach ($tasks as $task): ?><li class="task-row<?= $task['status'] === 'completed' ? ' is-complete' : '' ?>"><span class="subject-dot" style="--subject-color: <?= e($subject['color']) ?>"></span><div class="task-details"><a class="task-title task-link" href="<?= e(url('/tasks/' . $task['id'] . '/edit')) ?>"><?= e($task['title']) ?></a><span class="task-meta"><?= $task['due_date'] ? 'Due ' . e(date('M j, Y', strtotime($task['due_date']))) : 'No deadline' ?></span></div><span class="status-pill status-<?= e($task['status']) ?>"><?= e(ucwords(str_replace('_', ' ', $task['status']))) ?></span><span class="priority priority-<?= e($task['priority']) ?>"><?= e(ucfirst($task['priority'])) ?></span></li><?php endforeach; ?></ul>
    <?php endif; ?>
    <form class="danger-zone" method="post" action="<?= e(url('/subjects/' . $subject['id'] . '/delete')) ?>"><?= csrf_field() ?><p>Deleting a subject keeps its tasks, but removes their subject assignment.</p><button class="danger-button" type="submit" data-confirm="Delete this subject? Tasks will be kept without a subject.">Delete subject</button></form>
</section>